/**
 * Reading level: the same lesson, written for the age reading it.
 *
 * The corpus was authored at one register, roughly late-high-school, and it
 * shows: "financially literate individuals accumulate 75% more wealth over
 * their lifetimes" is a true sentence a twelve year old will not finish. The
 * fix is not a second corpus. It is letting any authored string carry an
 * age-banded variant, and collapsing it to one string before the lesson is ever
 * handed to a renderer.
 *
 * Three bands, because three is where the writing actually changes:
 *
 *   middle  ~11-13  short sentences, no jargon, concrete nouns, small numbers
 *   high    ~14-18  the register the corpus is already written in (the DEFAULT)
 *   adult   18+     precise terms, denser prose, no hand-holding
 *
 * The resolution happens in loadCourseLessons, at the same choke point that
 * filters retired step types. That matters: every renderer, the validator, the
 * mobile sync and the Studio all keep seeing plain strings, so adding this cost
 * zero changes to the component layer and cannot half-apply.
 */

export type ReadingLevel = 'middle' | 'high' | 'adult';

export const READING_LEVELS: ReadingLevel[] = ['middle', 'high', 'adult'];

export const READING_LEVEL_LABELS: Record<ReadingLevel, { name: string; hint: string }> = {
  middle: { name: 'Simpler', hint: 'Short sentences, everyday words. Around ages 11 to 13.' },
  high: { name: 'Standard', hint: 'The usual level. Around ages 14 to 18.' },
  adult: { name: 'Advanced', hint: 'Full terminology, denser explanations. Adults.' },
};

export const DEFAULT_READING_LEVEL: ReadingLevel = 'high';

/**
 * An authored value that may be written once, or once per band.
 *
 * Authors write a plain string until a lesson actually needs to differ, so the
 * 300 lessons already in the corpus are valid `Leveled<string>` as they stand
 * and render exactly as before.
 */
export type Leveled<T = string> = T | Partial<Record<ReadingLevel, T>>;

/** Is this object a band map rather than the value itself? */
function isBandMap(v: unknown): v is Partial<Record<ReadingLevel, unknown>> {
  if (!v || typeof v !== 'object' || Array.isArray(v)) return false;
  const keys = Object.keys(v);
  return keys.length > 0 && keys.every((k) => (READING_LEVELS as string[]).includes(k));
}

/**
 * Pick a band, falling back toward the standard level rather than to nothing.
 * A lesson that only wrote a `middle` variant must still render for an adult.
 */
function pickBand<T>(map: Partial<Record<ReadingLevel, T>>, level: ReadingLevel): T | undefined {
  const order: ReadingLevel[] =
    level === 'middle' ? ['middle', 'high', 'adult']
    : level === 'adult' ? ['adult', 'high', 'middle']
    : ['high', 'adult', 'middle'];
  for (const b of order) {
    const v = map[b];
    if (v !== undefined) return v;
  }
  return undefined;
}

/**
 * Deep-collapse every band map in a lesson tree to the chosen level.
 *
 * Returns the input untouched when nothing is banded, so a corpus with no
 * variants authored costs one walk and allocates nothing.
 */
export function resolveReadingLevel<T>(node: T, level: ReadingLevel): T {
  if (Array.isArray(node)) {
    let changed = false;
    const out = node.map((n) => {
      const r = resolveReadingLevel(n, level);
      if (r !== n) changed = true;
      return r;
    });
    return (changed ? out : node) as T;
  }
  if (!node || typeof node !== 'object') return node;

  if (isBandMap(node)) {
    return resolveReadingLevel(pickBand(node as Partial<Record<ReadingLevel, unknown>>, level), level) as T;
  }

  let changed = false;
  const out: Record<string, unknown> = {};
  for (const [k, v] of Object.entries(node as Record<string, unknown>)) {
    const r = resolveReadingLevel(v, level);
    if (r !== v) changed = true;
    out[k] = r;
  }
  return (changed ? out : node) as T;
}

// ── the learner's own setting ───────────────────────────────────────────────

const STORAGE_KEY = 'euphoria_reading_level';

/**
 * Map a US grade level to a band, for learners who joined through a class and
 * never chose one themselves. Anything unrecognised falls to the default rather
 * than guessing.
 */
export function levelFromGrade(grade?: string | null): ReadingLevel | undefined {
  if (!grade) return undefined;
  const n = parseInt(String(grade).replace(/\D+/g, ''), 10);
  if (!Number.isFinite(n)) return undefined;
  if (n <= 8) return 'middle';
  if (n <= 12) return 'high';
  return 'adult';
}

export function readStoredLevel(): ReadingLevel | undefined {
  if (typeof window === 'undefined') return undefined;
  try {
    const v = localStorage.getItem(STORAGE_KEY);
    return (READING_LEVELS as string[]).includes(v ?? '') ? (v as ReadingLevel) : undefined;
  } catch {
    return undefined;
  }
}

export function storeLevel(level: ReadingLevel): void {
  try { localStorage.setItem(STORAGE_KEY, level); } catch { /* private mode */ }
  // Lessons are resolved at load, so anything already mounted needs to re-read.
  try { window.dispatchEvent(new CustomEvent('euphoria:reading-level', { detail: level })); } catch { /* SSR */ }
}

/** The level to render at right now. Explicit choice wins over grade. */
export function activeReadingLevel(grade?: string | null): ReadingLevel {
  return readStoredLevel() ?? levelFromGrade(grade) ?? DEFAULT_READING_LEVEL;
}
